<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref,reactive,watch } from 'vue';
import { ElMessage,ElMessageBox } from 'element-plus';
import { api,errorText } from '../../api/zenflow/client';
import References,{type ReferenceSelection} from './References.vue';
import PreviewCompare from './PreviewCompare.vue';
interface AnswerExample{user:string;assistant:string;avoid?:string;reason?:string;locale?:'zh-CN'|'en-US';tags?:string[]}
interface Authoring{principles:string;coreSummary:string;citationMode:string;examples:AnswerExample[]}
interface RetrievalPolicy{references:ReferenceSelection[];maxFragments:number;minScore:number}
interface Revision{retrievalPolicy:RetrievalPolicy;id:string;revisionNo:number;version:number;state:string;error_code?:string|null;active:boolean;authoring:Authoring;modelId:string|null;releaseDigest:string|null}
interface PublicationOperation{id:string;action:string;administrator:string;createdAt:string;previousRevisionNo:number|null;targetRevisionNo:number|null;changes:string[]}
interface Configuration{configured:boolean;status:string;bindingVersion:number;revisions:Revision[];operations?:PublicationOperation[]}
interface Model{id:string;name:string;published:boolean;tested:boolean;active:boolean}
const publicationDateFormat=new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'});
function publicationTime(value:string){return publicationDateFormat.format(new Date(value));}
const config=ref<Configuration>({configured:false,status:'DISABLED',bindingVersion:0,revisions:[]});
const models=ref<Model[]>([]),busy=ref(false),open=ref(false),previewOpen=ref(false),preview=ref(''),selected=ref<Revision>(),modelId=ref('');
const policy=reactive<RetrievalPolicy>({references:[],maxFragments:6,minScore:0.7});
const editorTab=ref('principles');
const props=withDefaults(defineProps<{initialTab?:string}>(),{initialTab:'principles'});
const pageTab=ref(props.initialTab),viewRevisionId=ref('');
const viewRevision=computed(()=>config.value.revisions.find(row=>row.id===viewRevisionId.value));
const onlineRevision=computed(()=>config.value.revisions.find(row=>row.active));
const revisionChanges=computed(()=>{
 const before=onlineRevision.value,after=viewRevision.value;if(!before||!after)return [];
 const entries:{label:string;value:(row:Revision)=>unknown;format?:(row:Revision)=>string}[]=[
  {label:'陪伴原则',value:row=>row.authoring.principles},{label:'核心提要',value:row=>row.authoring.coreSummary},
  {label:'回答示例',value:row=>row.authoring.examples,format:row=>row.authoring.examples.map((example,i)=>'示例 '+(i+1)+'\n用户：'+example.user+'\n回应：'+example.assistant+(example.avoid?'\n不建议：'+example.avoid:'')+(example.reason?'\n原因：'+example.reason:'')+(example.locale?'\n语言：'+(example.locale==='zh-CN'?'中文':'English'):'')+(example.tags?.length?'\n标签：'+example.tags.join('、'):'')).join('\n\n')||'无示例'},{label:'引用方式',value:row=>row.authoring.citationMode,format:row=>row.authoring.citationMode==='VISIBLE'?'展示引用':'按需引用'},
  {label:'参考内容',value:row=>row.retrievalPolicy.references.map(item=>[item.documentId,item.kind,item.locale,item.citationVisibility,item.mode||'RETRIEVAL']),format:row=>row.retrievalPolicy.references.map(item=>'资料 '+item.documentId+' · '+(item.kind==='EXAMPLE'?'示例资料':'参考材料')+' · '+(item.locale==='zh-CN'?'中文':'English')+' · '+(item.citationVisibility==='PUBLIC'?'公开引用':item.citationVisibility==='TITLE_ONLY'?'仅显示标题':'内部参考')).join('\n')||'无参考资料'},
  {label:'检索范围',value:row=>[row.retrievalPolicy.maxFragments,row.retrievalPolicy.minScore],format:row=>'最多 '+row.retrievalPolicy.maxFragments+' 个片段，最低相关性 '+row.retrievalPolicy.minScore},
  {label:'固定模型',value:row=>row.modelId,format:row=>models.value.find(model=>model.id===row.modelId)?.name||(row.modelId?'配置 '+row.modelId:'尚未绑定模型')}
 ];
 const display=(value:unknown)=>typeof value==='string'?(value||'空'):(JSON.stringify(value,null,2)||'未设置');
 return entries.filter(entry=>JSON.stringify(entry.value(before))!==JSON.stringify(entry.value(after))).map(entry=>({label:entry.label,before:entry.format?entry.format(before):display(entry.value(before)),after:entry.format?entry.format(after):display(entry.value(after))}));
});
watch(()=>config.value.revisions,rows=>{if(!rows.some(row=>row.id===viewRevisionId.value))viewRevisionId.value=rows.find(row=>row.active)?.id||rows.find(row=>row.state==='DRAFT')?.id||rows[0]?.id||'';});
let editorOriginal='';
let configurationEpoch=0;
function editorSnapshot(){return JSON.stringify({form,policy});}
async function closeEditor(done:()=>void){if(busy.value)return;if(editorOriginal!==editorSnapshot()){try{await ElMessageBox.confirm('陪伴草稿有未保存修改，是否放弃？公共资料中已单独保存的内容会保留。','放弃草稿修改',{confirmButtonText:'放弃',cancelButtonText:'继续编辑'});}catch{return;}}done();}
const form=reactive<Authoring>({principles:'',coreSummary:'',citationMode:'ON_DEMAND',examples:[]});
async function load(){configurationEpoch++;busy.value=true;try{const [a,b]=await Promise.all([api.get('/companion'),api.get('/models')]);config.value=a.data;models.value=b.data;modelId.value=models.value.find(m=>m.active)?.id||'';}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function create(row?:Revision){configurationEpoch++;busy.value=true;try{config.value=(await api.post('/companion/drafts',row?{fromRevisionId:row.id}:{})).data;ElMessage.success('草稿已创建');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
function edit(row:Revision,tab='principles'){selected.value=row;Object.assign(form,JSON.parse(JSON.stringify(row.authoring)));Object.assign(policy,row.retrievalPolicy||{references:[],maxFragments:6,minScore:0.7});policy.references=JSON.parse(JSON.stringify(policy.references));if(!policy.maxFragments)policy.maxFragments=6;editorTab.value=tab;editorOriginal=editorSnapshot();open.value=true;}
async function save(){if(!selected.value)return;configurationEpoch++;busy.value=true;try{config.value=(await api.put('/companion/revisions/'+selected.value.id,{expectedVersion:selected.value.version,authoring:{...form,examples:form.examples.map(example=>({...example,...(example.locale?{}:{locale:undefined})}))},retrievalPolicy:{...policy,maxFragments:policy.references.some(ref=>ref.mode!=='FIXED')?policy.maxFragments:0}})).data;editorOriginal=editorSnapshot();open.value=false;ElMessage.success('草稿已保存');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
function preparationError(code:string){const messages:Record<string,string>={REFERENCE_INDEX_NOT_READY:'参考资料索引尚未就绪，完成准备后才可发布。',REFERENCE_SOURCE_REVOKED:'参考资料已撤销，请重新选材并创建草稿。',COMPANION_MODEL_CHANGED:'模型配置已变化，请复制草稿后重新准备。',COMPANION_PREPARE_RETRY_EXHAUSTED:'准备任务多次中断，可再次重试。'};return messages[code]||'版本准备未完成，请检查模型和资料配置后重试。';}
async function prepare(row:Revision){const chosenModel=row.state==='FAILED'&&row.modelId?row.modelId:modelId.value;if(!chosenModel){ElMessage.warning('请先测试并激活模型');return;}configurationEpoch++;busy.value=true;try{config.value=(await api.post('/companion/revisions/'+row.id+'/prepare',{expectedVersion:row.version,modelId:chosenModel})).data;ElMessage.success('已提交准备任务，完成后可预览和发布');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function publish(row:Revision){try{await ElMessageBox.confirm('发布后，聊天与创作的新一轮请求将使用版本 '+row.revisionNo+'。确认发布？','发布陪伴版本',{confirmButtonText:'发布版本',cancelButtonText:'继续检查'});}catch{return;}configurationEpoch++;busy.value=true;try{config.value=(await api.post('/companion/revisions/'+row.id+'/publish',{expectedBindingVersion:config.value.bindingVersion})).data;ElMessage.success('陪伴版本已发布');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function disable(){configurationEpoch++;busy.value=true;try{config.value=(await api.post('/companion/disable',{expectedBindingVersion:config.value.bindingVersion})).data;ElMessage.success('陪伴已停用');}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
async function showPreview(row:Revision){configurationEpoch++;busy.value=true;try{const data=(await api.get('/companion/revisions/'+row.id+'/preview')).data;preview.value=data.instructions||data.authoring.principles+'\n\n'+data.authoring.coreSummary;previewOpen.value=true;}catch(e){ElMessage.error(errorText(e));}finally{busy.value=false;}}
let refreshTimer:ReturnType<typeof setInterval>|undefined;
let disposed=false,refreshing=false;
onMounted(()=>{void load();refreshTimer=setInterval(async()=>{
 if(disposed||busy.value||refreshing||!config.value.revisions.some(row=>row.state==='PREPARING'))return;
 const requestEpoch=configurationEpoch;refreshing=true;try{const result=await api.get('/companion');if(!disposed&&!busy.value&&requestEpoch===configurationEpoch&&JSON.stringify(config.value)!==JSON.stringify(result.data))config.value=result.data;}catch{}finally{refreshing=false;}
},3000);});
onUnmounted(()=>{disposed=true;if(refreshTimer)clearInterval(refreshTimer);});
</script>
<template><div><div class="page-heading"><div><div class="eyebrow">COMPANION PRINCIPLES</div><h1>{{initialTab==='examples'?'回答示例':'陪伴配置'}}</h1><p class="muted">编辑原则与示例，准备后发布。历史版本可重新发布以回滚。</p></div><el-button type="primary" :disabled="busy" @click="create()">新建草稿</el-button></div>
 <el-alert :title="config.status==='ENABLED'?'陪伴已启用，新一轮使用当前发布版本。':'陪伴尚未启用，请先配置模型并发布陪伴版本。'" :type="config.status==='ENABLED'?'success':'info'" :closable="false"/>
 <div class="actions" style="margin:20px 0"><el-select v-model="modelId" placeholder="选择已测试并发布的模型" style="width:320px" :disabled="busy"><el-option v-for="m in models.filter(x=>x.published&&x.tested)" :key="m.id" :label="m.name" :value="m.id"/></el-select><el-button :disabled="busy||config.status!=='ENABLED'" @click="disable">停用陪伴</el-button><el-button :disabled="busy" @click="load">刷新</el-button></div>
 <el-tabs v-model="pageTab">
 <el-tab-pane v-for="tab in [{name:'principles',label:'陪伴原则'},{name:'references',label:'参考内容'},{name:'examples',label:'回答示例'}]" :key="tab.name" :name="tab.name" :label="tab.label">
 <div class="actions" style="margin:16px 0"><el-select v-model="viewRevisionId" placeholder="选择版本"><el-option v-for="row in config.revisions" :key="row.id" :value="row.id" :label="'版本 '+row.revisionNo+(row.active?' · 当前线上':' · '+row.state)"/></el-select><el-button v-if="viewRevision?.state==='DRAFT'" :disabled="busy" @click="edit(viewRevision,tab.name)">编辑{{tab.label}}</el-button><el-button v-else-if="viewRevision" :disabled="busy" @click="create(viewRevision)">复制为草稿后修改</el-button></div>
 <el-alert v-if="viewRevision&&onlineRevision" :title="revisionChanges.length?'与线上版本 '+onlineRevision.revisionNo+' 的差异：'+revisionChanges.map(change=>change.label).join('、'):'与当前线上版本的原则、资料、示例、检索范围和模型一致'" type="info" :closable="false"/>
 <el-collapse v-if="revisionChanges.length"><el-collapse-item title="查看逐项差异" name="differences"><el-table :data="revisionChanges" max-height="520"><el-table-column prop="label" label="变更项" width="110"/><el-table-column label="当前线上" min-width="180"><template #default="{row}"><p class="authored-text">{{row.before}}</p></template></el-table-column><el-table-column label="所选版本" min-width="180"><template #default="{row}"><p class="authored-text">{{row.after}}</p></template></el-table-column></el-table></el-collapse-item></el-collapse>
 <el-empty v-if="!viewRevision" description="新建草稿，开始维护陪伴配置。"/>
 <template v-else><template v-if="tab.name==='principles'"><h2>陪伴原则</h2><p class="authored-text">{{viewRevision.authoring.principles||'尚未填写'}}</p><h2>核心提要</h2><p class="authored-text">{{viewRevision.authoring.coreSummary||'尚未填写'}}</p><p class="muted">引用方式：{{viewRevision.authoring.citationMode==='VISIBLE'?'展示引用':'按需引用'}}</p></template>
 <template v-else-if="tab.name==='references'"><p class="muted">本轮最多 {{viewRevision.retrievalPolicy.maxFragments}} 个片段 · 最低相关性 {{viewRevision.retrievalPolicy.minScore}}</p><el-empty v-if="!viewRevision.retrievalPolicy.references.length" description="此版本没有选入参考资料。"/><el-table v-else :data="viewRevision.retrievalPolicy.references"><el-table-column prop="documentId" label="资料编号"/><el-table-column label="关联方式"><template #default="{row}">{{row.mode==='FIXED'?'固定短参考':'检索参考'}}</template></el-table-column><el-table-column prop="kind" label="资料类型"/><el-table-column prop="locale" label="语言"/><el-table-column prop="citationVisibility" label="引用显示"/></el-table></template>
 <template v-else><el-empty v-if="!viewRevision.authoring.examples.length" description="此版本尚无回答示例。"/><article v-for="(example,index) in viewRevision.authoring.examples" :key="index" class="model-card"><h2>示例 {{index+1}}</h2><h3>用户表达</h3><p class="authored-text">{{example.user}}</p><h3>陪伴者回应</h3><p class="authored-text">{{example.assistant}}</p><template v-if="example.avoid"><h3>不建议回答</h3><p class="authored-text">{{example.avoid}}</p></template><p v-if="example.reason" class="authored-text">原因：{{example.reason}}</p><p class="muted">{{example.locale||'未指定语言'}} · {{example.tags?.join('、')||'无评价标签'}}</p></article></template></template>
 </el-tab-pane>
 <el-tab-pane name="compare" label="试聊与比较"><PreviewCompare :revisions="config.revisions" :models="models" :online="config.status==='ENABLED'"/></el-tab-pane>
 <el-tab-pane name="releases" label="发布与记录"><h2>操作记录</h2><p class="muted">记录启用、回滚与停用的实际操作，时间按当前设备时区显示。旧版本没有操作记录时，不补写历史。</p><el-empty v-if="!config.operations?.length" description="尚无发布操作记录。"/><el-table v-else :data="config.operations" max-height="360"><el-table-column label="操作" width="90"><template #default="{row}">{{row.action==='DISABLE'?'停用':row.action==='ROLLBACK'?'回滚':'发布'}}</template></el-table-column><el-table-column prop="administrator" label="操作人"/><el-table-column label="时间" min-width="160"><template #default="{row}">{{publicationTime(row.createdAt)}}</template></el-table-column><el-table-column label="版本" min-width="150"><template #default="{row}">{{row.previousRevisionNo?'版本 '+row.previousRevisionNo:'未启用'}} → {{row.targetRevisionNo?'版本 '+row.targetRevisionNo:'停用'}}</template></el-table-column><el-table-column label="变更项" min-width="200"><template #default="{row}">{{row.changes.join('、')}}</template></el-table-column></el-table><h2>配置版本</h2><el-empty v-if="!config.revisions.length" description="新建草稿，开始维护陪伴原则。"/>
 <div v-loading="busy" class="models"><article v-for="row in config.revisions" :key="row.id" class="model-card"><div class="card-heading"><h2>版本 {{row.revisionNo}}</h2><el-tag :type="row.active?'success':'info'">{{row.active?'当前发布':row.state==='READY'?'已准备':row.state==='DRAFT'?'草稿':row.state==='PREPARING'?'准备中':row.state==='FAILED'?'准备失败':row.state}}</el-tag></div><p style="white-space:pre-wrap">{{row.authoring.coreSummary||row.authoring.principles.slice(0,120)}}</p><p class="muted">{{row.retrievalPolicy?.references.length||0}} 份参考资料 · {{row.authoring.examples.length}} 个回应示例 · {{row.authoring.citationMode==='VISIBLE'?'展示引用':'按需引用'}}</p><p v-if="row.error_code" class="muted">{{preparationError(row.error_code)}}</p><div class="actions"><el-button :disabled="busy" @click="showPreview(row)">预览</el-button><el-button v-if="row.state==='DRAFT'" :disabled="busy" @click="edit(row)">编辑</el-button><el-button v-if="row.state==='DRAFT'||row.state==='FAILED'" :disabled="busy||(!modelId&&!row.modelId)" @click="prepare(row)">{{row.state==='FAILED'?'重试准备':'准备版本'}}</el-button><el-button v-if="row.state==='READY'" type="primary" :disabled="busy||row.active" @click="publish(row)">{{row.active?'已发布':'发布此版本'}}</el-button><el-button v-if="row.state!=='DRAFT'" :disabled="busy" @click="create(row)">复制为草稿</el-button></div></article></div>
 </el-tab-pane></el-tabs>
 <el-dialog v-model="open" title="编辑陪伴原则" width="min(760px,94vw)" :close-on-click-modal="false" :before-close="closeEditor"><el-tabs v-model="editorTab"><el-tab-pane label="陪伴原则" name="principles"><el-form label-position="top"><el-form-item label="陪伴原则"><el-input v-model="form.principles" type="textarea" :rows="7" maxlength="8000" show-word-limit/></el-form-item><el-form-item label="核心提要"><el-input v-model="form.coreSummary" type="textarea" :rows="3" maxlength="4000" show-word-limit/></el-form-item><el-form-item label="引用方式"><el-select v-model="form.citationMode"><el-option label="按需引用" value="ON_DEMAND"/><el-option label="展示引用" value="VISIBLE"/></el-select></el-form-item></el-form></el-tab-pane><el-tab-pane label="参考资料" name="references"><References v-model:selected="policy.references"/><el-form label-position="top"><el-form-item label="本轮最多检索片段"><el-input-number v-model="policy.maxFragments" :min="1" :max="6"/></el-form-item><el-form-item label="最低相关性"><el-input-number v-model="policy.minScore" :min="0" :max="1" :step="0.05"/></el-form-item></el-form></el-tab-pane><el-tab-pane label="回答示例" name="examples"><el-form label-position="top"><div v-for="(example,i) in form.examples" :key="i"><el-form-item :label="'示例 '+(i+1)+' · 用户表达'"><el-input v-model="example.user" type="textarea" maxlength="2000"/></el-form-item><el-form-item label="陪伴者回应"><el-input v-model="example.assistant" type="textarea" :rows="3" maxlength="3000"/></el-form-item><el-form-item label="不建议回答"><el-input v-model="example.avoid" type="textarea" :rows="2" maxlength="3000" placeholder="反例仅用于说明应避免的表达"/></el-form-item><el-form-item label="原因"><el-input v-model="example.reason" type="textarea" :rows="2" maxlength="1000"/></el-form-item><el-form-item label="示例语言"><el-select v-model="example.locale" clearable><el-option label="中文" value="zh-CN"/><el-option label="English" value="en-US"/></el-select></el-form-item><el-form-item label="评价标签"><el-select v-model="example.tags" multiple filterable allow-create default-first-option :multiple-limit="6" placeholder="输入标签，最多 6 个，每个不超过 40 字"/></el-form-item><el-button text @click="form.examples.splice(i,1)">移除此示例</el-button></div><el-button :disabled="form.examples.length>=6" @click="form.examples.push({user:'',assistant:''})">添加回应示例</el-button></el-form></el-tab-pane></el-tabs><template #footer><el-button :disabled="busy" @click="closeEditor(()=>open=false)">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存草稿</el-button></template></el-dialog>
 <el-dialog v-model="previewOpen" title="陪伴版本预览" width="min(800px,94vw)"><p class="muted">仅展示后台编写的原则与编译结果。此预览未调用模型。</p><pre style="white-space:pre-wrap;line-height:1.8">{{preview}}</pre></el-dialog>
</div></template>

<style scoped>.authored-text{white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere}</style>
